script:
(function () {
  'use strict';
  // Balloon loan: monthly payments sized as if the loan ran for the full amortization term, with the
  // remaining balance due as one lump sum after the balloon term.
  //   Amortizing: M = L * i / (1 - (1 + i)^-n), i = rate / 12, n = amortization years * 12 (L / n at 0%)
  //   Interest-only: M = L * i, balance never falls, so the balloon equals the loan amount.
  //   Balloon = balance after b regular payments (b = balloon years * 12), paid with/after payment b:
  //     B = L(1+i)^b - M((1+i)^b - 1) / i
  // Verified (Node, scratchpad tests/w3b2e): $200,000 at 6% over 30 years -> $1,199.10/month;
  //   balance after 84 payments $179,278.77, total interest $80,003.26 (month-by-month loop = closed form above to the cent);
  //   balloon at the full term = $0; 0% rate: $120,000 over 10 yrs, balloon after 5 -> $1,000.00 and
  //   $60,000.00; interest-only $100,000 at 6% -> $500.00/month and a $100,000 balloon.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var pct = new Intl.NumberFormat('en-US', { style: 'percent', maximumFractionDigits: 1 });
  var last = null;

  function el(id) { return document.getElementById(id); }
  function setText(id, t) { el(id).textContent = t; }

  function read(id) {
    var raw = String(el(id).value).trim();
    if (raw === '') return NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function monthlyPayment(principal, annualRate, months) {
    if (months <= 0 || principal <= 0) return 0;
    var i = annualRate / 12;
    if (i === 0) return principal / months;
    return principal * i / (1 - Math.pow(1 + i, -months));
  }

  function schedule(loan, rate, amortMonths, balloonMonths, interestOnly) {
    var i = rate / 12;
    var pay = interestOnly ? loan * i : monthlyPayment(loan, rate, amortMonths);
    var bal = loan, rows = [], totalInterest = 0, totalPaid = 0;
    for (var m = 1; m <= balloonMonths; m++) {
      if (bal <= 0.005) { bal = 0; break; }
      var interest = bal * i;
      var principal = interestOnly ? 0 : Math.min(pay - interest, bal);
      bal -= principal;
      if (bal < 0.005) bal = 0;
      totalInterest += interest;
      totalPaid += principal + interest;
      rows.push({ n: m, payment: principal + interest, principal: principal, interest: interest, balance: bal });
    }
    return { payment: pay, rows: rows, balloon: bal, totalInterest: totalInterest, regularPaid: totalPaid };
  }

  function clear() {
    ['blPayment', 'blBalloon', 'blTotalInterest', 'blTotalPaid', 'blRegularPaid', 'blPrincipalPaid',
     'blBalloonShare', 'blCount'].forEach(function (id) { setText(id, '–'); });
    el('blSchedule').innerHTML = '';
    last = null;
  }

  function renderSchedule() {
    var body = el('blSchedule'), head = el('blScheduleHead');
    if (!last) { body.innerHTML = ''; return; }
    var html = [];
    var balloonRow = function (label) {
      return '<tr><td>' + label + '</td><td colspan="2">Balloon payment</td><td>' + money.format(last.balloon) + '</td><td>' + money.format(0) + '</td></tr>';
    };
    if (el('blView').value === 'month') {
      head.innerHTML = '<tr><th scope="col">Payment</th><th scope="col">Principal</th><th scope="col">Interest</th><th scope="col">Total paid</th><th scope="col">Balance</th></tr>';
      last.rows.forEach(function (r) {
        html.push('<tr><td>' + r.n + '</td><td>' + money.format(r.principal) + '</td><td>' + money.format(r.interest) +
          '</td><td>' + money.format(r.payment) + '</td><td>' + money.format(r.balance) + '</td></tr>');
      });
      if (last.balloon > 0) html.push(balloonRow('Final'));
    } else {
      head.innerHTML = '<tr><th scope="col">Year</th><th scope="col">Principal</th><th scope="col">Interest</th><th scope="col">Total paid</th><th scope="col">Ending balance</th></tr>';
      var p = 0, it = 0;
      last.rows.forEach(function (r, idx) {
        p += r.principal; it += r.interest;
        if (r.n % 12 === 0 || idx === last.rows.length - 1) {
          html.push('<tr><td>' + Math.ceil(r.n / 12) + '</td><td>' + money.format(p) + '</td><td>' + money.format(it) +
            '</td><td>' + money.format(p + it) + '</td><td>' + money.format(r.balance) + '</td></tr>');
          p = 0; it = 0;
        }
      });
      if (last.balloon > 0) html.push(balloonRow('End'));
    }
    body.innerHTML = html.join('');
  }

  function update() {
    var loan = read('blLoan'), rate = read('blRate'), amortYears = read('blAmort'), balloonYears = read('blBalloonYears');
    var interestOnly = el('blType').value === 'interest';
    el('blAmortWrap').hidden = interestOnly;
    var err = el('blError'), msg = '';
    if ([loan, rate, balloonYears].some(isNaN) || (!interestOnly && isNaN(amortYears))) msg = 'Fill in every field with a number.';
    else if (loan <= 0 || loan > 1e10) msg = 'Enter a loan amount above $0.';
    else if (rate < 0 || rate > 50) msg = 'Enter an interest rate from 0% to 50%.';
    else if (balloonYears <= 0 || balloonYears > 50 || Math.round(balloonYears * 12) < 1) msg = 'Enter a balloon term of 1 month to 50 years.';
    else if (!interestOnly && (amortYears <= 0 || amortYears > 50)) msg = 'Enter an amortization term of up to 50 years.';
    else if (!interestOnly && balloonYears > amortYears) msg = 'The balloon term can\'t be longer than the amortization term.';
    err.hidden = !msg;
    if (msg) { err.textContent = msg; clear(); return; }

    var amortMonths = Math.round(amortYears * 12), balloonMonths = Math.round(balloonYears * 12);
    var r = schedule(loan, rate / 100, amortMonths, balloonMonths, interestOnly);
    last = r;
    setText('blPayment', money.format(r.payment));
    setText('blBalloon', money.format(r.balloon));
    setText('blTotalInterest', money.format(r.totalInterest));
    setText('blTotalPaid', money.format(r.regularPaid + r.balloon));
    setText('blRegularPaid', money.format(r.regularPaid));
    setText('blPrincipalPaid', money.format(loan - r.balloon));
    setText('blBalloonShare', pct.format(r.balloon / loan));
    setText('blCount', String(r.rows.length));
    renderSchedule();
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('blForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    el('blView').addEventListener('change', renderSchedule);
    update();
  });
})();
